(function () {
var DOC_WORDS = 600;
var ANS_START_WORDS = 250;
var ANS_END_WORDS = 310;
var SCALE = 0.6;
var ctl = document.getElementById("chunk");
var svg = document.getElementById("bench-art");
var knob = document.getElementById("art-knob");
var hl = document.getElementById("art-hl");
var ticks = document.getElementById("art-ticks");

function bestChunk(chunkWords) {
  var best = { k: 0, overlapWords: -1 };
  for (var k = 0; k * chunkWords < DOC_WORDS; k++) {
    var a = k * chunkWords;
    var b = Math.min(a + chunkWords, DOC_WORDS);
    var o = Math.min(b, ANS_END_WORDS) - Math.max(a, ANS_START_WORDS);
    if (o < 0) o = 0;
    if (o > best.overlapWords) best = { k: k, overlapWords: o };
  }
  return best;
}

function update() {
  var c = Number(ctl.value);
  var b = bestChunk(c);
  var ansWords = ANS_END_WORDS - ANS_START_WORDS;
  var cover = Math.round(b.overlapWords / ansWords * 100);
  var pure = Math.round(b.overlapWords / c * 100);
  var count = Math.ceil(DOC_WORDS / c);
  var x = 20 + b.k * c * SCALE;
  var w = Math.min(c, DOC_WORDS - b.k * c) * SCALE;
  hl.setAttribute("x", x);
  hl.setAttribute("width", w);
  var d = "";
  for (var k = 1; k * c < DOC_WORDS; k++) {
    var tx = 20 + k * c * SCALE;
    d += "M" + tx + " 60V100";
  }
  ticks.setAttribute("d", d);
  var min = Number(ctl.min), max = Number(ctl.max);
  knob.setAttribute("cx", 40 + (c - min) / (max - min) * 320);
  document.getElementById("cover").textContent = cover + " %";
  document.getElementById("pure").textContent = pure + " %";
  document.getElementById("count").textContent = count + " chunks";
  var msg = "Chunk size " + c + " words: the best chunk holds " + cover + " percent of the answer, and " + pure + " percent of it is answer.";
  svg.setAttribute("aria-label", msg);
  document.getElementById("found").textContent = "With chunks of " + c + " words, the best chunk holds " + cover + " % of the answer and " + pure + " % of that chunk is answer, across " + count + " chunks.";
}

var held = false;
function moveTo(ev) {
  var r = svg.getBoundingClientRect();
  var vx = (ev.clientX - r.left) / r.width * 400;
  var f = (vx - 40) / 320;
  if (f < 0) f = 0;
  if (f > 1) f = 1;
  var min = Number(ctl.min), max = Number(ctl.max), step = Number(ctl.step);
  var v = min + Math.round(f * (max - min) / step) * step;
  ctl.value = v;
  ctl.dispatchEvent(new Event("input", { bubbles: true }));
}
knob.addEventListener("pointerdown", function (ev) {
  held = true;
  knob.setPointerCapture(ev.pointerId);
  moveTo(ev);
});
knob.addEventListener("pointermove", function (ev) {
  if (held) moveTo(ev);
});
knob.addEventListener("pointerup", function () { held = false; });
knob.addEventListener("pointercancel", function () { held = false; });
ctl.addEventListener("input", update);
update();
})();</script></body></html>","citations":[{"source":"UNVERIFIED (no textbook page has been checked for this Environment)","page":null,"quote":null,"verified":false,"printedPage":null}],"checked":{"layers":["postprocess","scan","render","wording"],"controlsExercised":1,"gridPoints":0,"referenceCases":0,"readouts":3,"models":[],"limits":"Written whole by a model and not built on the Kit, so none of its numbers or formulas were compared with an audited science model. Code checked that it runs and that its controls work and a second model read its words and formulas, but only for a short, scripted stretch of time. No textbook source was checked and a person has not reviewed it. Check it against your textbook."},"planSummary":"A simple page written whole by a model, the last step when no fuller lab passed its checks (topic none)."}}
